select lm1_0.match_id,lm1_0.match_time,lm1_0.sets,lm1_0.stage_id,s1_0.stage_id,s1_0.end_date,s1_0.name,s1_0.is_regular,s1_0.stage_order,s1_0.start_date,lm1_0.team1_id,t1_0.team_id,t1_0.code,lm1_0.team2_id,t2_0.team_id,t2_0.code from lck_match lm1_0 join team t1_0 on t1_0.team_id=lm1_0.team1_id join team t2_0 on t2_0.team_id=lm1_0.team2_id join stage s1_0 on s1_0.stage_id=lm1_0.stage_id where lm1_0.match_time>='2026-04-20 00:00:00' and lm1_0.match_time<'2026-04-27 00:00:00' and (null is null or s1_0.stage_id=null) and (null is null or t1_0.team_id=null or t2_0.team_id=null) order by lm1_0.match_time
